import type { Handle, HandleServerError } from '@sveltejs/kit';
import { validateDebugToken } from '$lib/server/debug-helpers';

export const handle: Handle = async ({ event, resolve }) => {
  // Debug API auth — gate /api/debug/* behind Bearer token
  if (event.url.pathname.startsWith('/api/debug/')) {
    const auth = event.request.headers.get('authorization');
    if (!validateDebugToken(auth, env.DEBUG_API_TOKEN)) {
      return json({ error: 'Unauthorized' }, { status: 401 });
    }
  }

  const response = await resolve(event);
  if (
    event.request.method === 'GET' &&
    (response.headers.get('content-type') ?? '').includes('text/html')
  ) {
    // If the request carries the recently-viewed cookie the response is personalised,
    // so it must not be stored in a shared cache (CDN). Non-cookied visitors (first-time
    // or cleared) are safe to cache publicly.
    const personalized = event.request.headers.get('cookie')?.includes('rv=') ?? false;
    response.headers.set(
      'Cache-Control',
      personalized
        ? 'private, max-age=0'
        : 'public, max-age=0, s-maxage=30, stale-while-revalidate=60',
    );
  }
  return response;
};

export const handleError: HandleServerError = ({ error, event, status }) => {
  // Log server-side errors with context (avoids leaking stack traces to the client)
  const message = error instanceof Error ? error.message : 'Unknown error';
  console.error(`[server error] ${status} on ${event.url.pathname}: ${message}`);

  // Return a safe, generic message to the client
  return {
    message: status === 404 ? 'Not found' : 'An unexpected error occurred',
  };
};

import type { RequestHandler } from './$types';
import { getDb } from '$lib/server/db';
import { debugResponse, debugError, validateSqlQuery } from '$lib/server/debug-helpers';
import { sql } from 'drizzle-orm';

/**
 * POST /api/debug/sql
 * Body: { "sql": "SELECT * FROM flights LIMIT 10" }
 *
 * Only SELECT, EXPLAIN, SHOW, DESCRIBE, and WITH (CTE) are allowed.
 * All other statements are rejected with 403.
 * Queries have a 30-second timeout via statement_timeout.
 */
export const POST: RequestHandler = async ({ request }) => {
  const t0 = performance.now();
  try {
    const body = await request.json() as { sql?: string };
    const query = body.sql?.trim();

    if (!query) return debugError('Missing "sql" field in request body', 400);

    // Validate query (SELECT-only, no dangerous keywords)
    const validation = validateSqlQuery(query);
    if (!validation.valid) {
      return debugError(validation.error, 403);
    }

    // Get the underlying pg pool for raw SQL execution
    const d = getDb();

    // Set session-level timeout for this query only, then reset
    await d.execute(sql`SET SESSION statement_timeout = '30s'`);

    let result;
    try {
      result = await d.execute(sql`${sql.raw(query)}`);
    } finally {
      await d.execute(sql`RESET statement_timeout`);
    }

    const queryMs = performance.now() - t0;

    // Log query for audit
    const truncated = query.length > 200 ? query.substring(0, 200) + '...' : query;
    console.log(`[debug/sql] ${queryMs}ms | rows=${result.rows.length} | ${truncated}`);

    return debugResponse(result.rows, queryMs);
  } catch (err) {
    const queryMs = performance.now() - t0;
    const message = err instanceof Error ? err.message : 'Query failed';
    console.error(`[debug/sql] ERROR ${queryMs}ms | ${message}`);
    return debugError(message, 500);
  }
};

import type { RequestHandler } from './$types';
import { db, flightNotes } from '$lib/server/db';
import { debugResponse, debugError, parsePagination } from '$lib/server/debug-helpers';
import { eq, gte, lte, and, asc, desc } from 'drizzle-orm';

export const GET: RequestHandler = async ({ url }) => {
  const t0 = performance.now();
  try {
    const { limit, offset } = parsePagination(url.searchParams);
    const conditions = [];

    const flightId = url.searchParams.get('flight_id');
    if (flightId) conditions.push(eq(flightNotes.flightId, parseInt(flightId, 10)));

    const from = url.searchParams.get('from');
    if (from) conditions.push(gte(flightNotes.timestamp, new Date(from)));
    const to = url.searchParams.get('to');
    if (to) conditions.push(lte(flightNotes.timestamp, new Date(to)));

    const sortOrder = url.searchParams.get('order') === 'asc' ? asc : desc;

    const rows = conditions.length > 0
      ? await db.select().from(flightNotes).where(and(...conditions)).orderBy(sortOrder(flightNotes.timestamp)).limit(limit).offset(offset)
      : await db.select().from(flightNotes).orderBy(sortOrder(flightNotes.timestamp)).limit(limit).offset(offset);

    return debugResponse(rows, performance.now() - t0);
  } catch (err) {
    console.error('[debug/flight-notes]', err);
    return debugError('Query failed', 500);
  }
};

import type { RequestHandler } from './$types';
import { db, pushSubscriptions } from '$lib/server/db';
import { debugResponse, debugError, parsePagination } from '$lib/server/debug-helpers';
import { eq, gte, lte, and, asc, desc } from 'drizzle-orm';

export const GET: RequestHandler = async ({ url }) => {
  const t0 = performance.now();
  try {
    const { limit, offset } = parsePagination(url.searchParams);
    const conditions = [];

    const flightId = url.searchParams.get('flight_id');
    if (flightId) conditions.push(eq(pushSubscriptions.flightId, parseInt(flightId, 10)));

    const flightCode = url.searchParams.get('flight_code');
    if (flightCode) conditions.push(eq(pushSubscriptions.flightCode, flightCode.toUpperCase()));

    const dateFrom = url.searchParams.get('from');
    if (dateFrom) conditions.push(gte(pushSubscriptions.flightDate, dateFrom));
    const dateTo = url.searchParams.get('to');
    if (dateTo) conditions.push(lte(pushSubscriptions.flightDate, dateTo));

    const sortOrder = url.searchParams.get('order') === 'asc' ? asc : desc;

    const rows = conditions.length > 0
      ? await db.select().from(pushSubscriptions).where(and(...conditions)).orderBy(sortOrder(pushSubscriptions.createdAt)).limit(limit).offset(offset)
      : await db.select().from(pushSubscriptions).orderBy(sortOrder(pushSubscriptions.createdAt)).limit(limit).offset(offset);

    return debugResponse(rows, performance.now() - t0);
  } catch (err) {
    console.error('[debug/push-subs]', err);
    return debugError('Query failed', 500);
  }
};

